/* ============================================================
   أطياب الجاسم (React) — صفحة طرق الدفع (PaymentMethodPage)

   تعرض بطاقة لكل طريقة دفع (PaymentMethod) حتى تنتهي القائمة، ثم
   خطوات التقسيط وملاحظات أمان الدفع — كلّها من القسم `payments` في
   ATYAB_INFO_PAGES.

   ★ PaymentMethod يقرأ بياناته من الخادم (تُمرَّر كـprops) —
     وإضافة طريقة جديدة تتم في الخادم فقط.
   ★ القائمة من الخادم وحده (storeInfo.payments) — بلا أي احتياط
     مضمّن: تحميل ← سكيلتون، فراغ ← رسالة نصية.
   ============================================================ */

import { useEffect } from "react";
import { usePageMeta } from "../usePageMeta.js";
import { ATYAB_INFO_PAGES } from "../data/appConfig.js";
import { T } from "../i18n.js";
import { useAppDispatch, useAppSelector } from "../redux/hooks.js";
import { loadStoreSection } from "../redux/slices/storeInfoSlice.js";
import PaymentMethod from "../components/Source/PaymentMethod.jsx";
import { PayMethodSkeleton } from "../components/Skeletons/index.js";
import { Icon } from "../components/Source/Icons.jsx";

function sectionsOf(key, kind) {
  const page = (ATYAB_INFO_PAGES || {})[key] || {};
  return (page.sections || []).filter(function (sec) {
    return sec.kind === kind;
  })[0];
}

export default function PaymentMethodPage() {
  const dispatch = useAppDispatch();
  const language = useAppSelector(function (s) {
    return s.ui.language;
  });
  const live = useAppSelector(function (s) {
    return s.storeInfo.payments;
  });
  const page = (ATYAB_INFO_PAGES && ATYAB_INFO_PAGES.payments) || {};
  const steps = sectionsOf("payments", "steps");
  const facts = sectionsOf("payments", "facts");

  /* ★ الجلب من الخادم مرة واحدة لكل زيارة (الشريحة تتذكّر ما وصل) */
  useEffect(
    function () {
      dispatch(loadStoreSection("payments"));
    },
    [dispatch]
  );

  const fetched = live && Array.isArray(live.items) ? live.items : [];
  const methods = fetched;
  const loading = !!(live && live.status === "loading") && !methods.length;
  const empty = !loading && !methods.length;

  usePageMeta({
    route: "info",
    titleAr: T(page.title, "ar"),
    titleEn: T(page.title, "en")
  });

  return (
    <section className="container view inf" id="infoView">
      <header className="inf-hero">
        <span className="inf-eyebrow">{T(page.eyebrow, language)}</span>
        <h1 className="inf-h1">
          {T(page.title, language)} <span className="gold-text">{T(page.titleGold, language)}</span>
        </h1>
        {page.lead ? <p className="inf-lead">{T(page.lead, language)}</p> : null}
      </header>

      <div className="inf-body">
        <section className="inf-block">
          {loading ? (
            <PayMethodSkeleton count={4} />
          ) : (
            <ul className="inf-payments">
              {methods.map(function (method, i) {
                return <PaymentMethod method={method} key={method.key || i} />;
              })}
            </ul>
          )}
          {empty ? (
            <div className="inf-state" role="status">
              <Icon name="info" className="inf-ico inf-ico--gold" strokeWidth={1.7} />
              <span>{language === "en" ? "No payment methods published yet." : "لم تُنشر طرق الدفع بعد."}</span>
            </div>
          ) : null}
        </section>

        {steps ? (
          <section className="inf-block">
            {steps.title ? <h2 className="inf-h2">{T(steps.title, language)}</h2> : null}
            <ol className="inf-steps">
              {(steps.items || []).map(function (item, i) {
                return (
                  <li key={i}>
                    <span>{T(item, language)}</span>
                  </li>
                );
              })}
            </ol>
          </section>
        ) : null}

        {facts ? (
          <section className="inf-block">
            {facts.title ? <h2 className="inf-h2">{T(facts.title, language)}</h2> : null}
            <ul className="inf-facts">
              {(facts.items || []).map(function (item, i) {
                return (
                  <li key={i}>
                    <Icon name={item.icon} className="inf-ico inf-ico--gold" strokeWidth={1.7} />
                    <span className="inf-fact-label">{T(item.label, language)}</span>
                    <b className="inf-fact-value">{T(item.value, language)}</b>
                  </li>
                );
              })}
            </ul>
          </section>
        ) : null}
      </div>
    </section>
  );
}
